Question 1 : For an input N=3 Output should be like this
1112  
3222  
3334
Solution :
CPP

```` ```
#include <bits/stdc++.h>
using namespace std;
void pattern(int n)
{
    for (int i = 1; i <= n; ++i) {
        if (i % 2 == 0) {
            cout << i + 1;
            for (int j = 1; j <= n; j++)
                cout << i;
            cout << "\n";
        }
        else {
            for (int j = 1; j <= n; j++)
                cout << i;
            cout << i + 1 << "\n";
        }
    }
}
int main()
{
    int n;
    cin >> n;
    pattern(n);
}
